    out=ROOT/'WOWSignal/steps/03-hebrew-gematria/run-010-six-lateral-exits'
    g=json.loads((out/'graph.json').read_text(encoding='utf-8'));nodes={tuple(n['coordinate']):n for n in g['nodes']};core=set(map(tuple,g['core']));native=json.loads((out/'transform_trials.json').read_text(encoding='utf-8'))
    boundary=[{'id':f'B{i:02}',**e} for i,e in enumerate(g['source_perimeter'],1)]
