        for op in t['operations']:
            incoming=json.loads(json.dumps(state));xy=tuple(op['coordinate']);node=nodes[xy];position=op['container_index']-1
            previous=t['coordinates'][position-1] if position else None;nextcell=t['coordinates'][position+1] if position+1<len(t['coordinates']) else None
            alternatives=[n for n in node['neighbors'] if n!=previous and n!=nextcell]
            ref={'route':t['route'],'direction':t['orientation'],'occurrence':op['occurrence'],'coordinate':list(xy),'glyph':op['glyph'],'container_value':op['numeric_container']}
            glyph=op['glyph'];bucket={'Α':'origin_occurrences','Ι':'instance_occurrences','Γ':'frame_occurrences','Κ':'context_occurrences','Θ':'constraint_occurrences','Λ':'lattice_occurrences','Ε':'threshold_occurrences','Δ':'change_occurrences','Β':'branch_occurrences','Ϛ':'unresolved_occurrences'}[glyph]
            # These state changes retain measured relationships and role-tagged
