            if alternatives:state['retained_branch_alternatives'].append({'at':list(xy),'occurrence':op['occurrence'],'neighbors':alternatives})
            observed={'cell':list(xy),'numeric_container':node['value'],'previous_container':previous,'next_container':nextcell,'other_neighbors':alternatives,'inside_core':xy in core,'adjacency_to_previous_confirmed':previous is None or previous in node['neighbors']}
            if glyph=='Α':
                prior=incoming['origin_occurrences'][-1] if incoming['origin_occurrences'] else None
                action={'book_ii_role':'Origin','contextual_application':'Address this distinct source occurrence as an origin in the retained incoming relation.','actual_relationship_recorded':{'previous_origin_occurrence':prior,'current_origin_occurrence':ref,'same_numeric_value_does_not_merge_source_identity':True},'semantic_resolution':'Source identity and arrival relationship are retained; no new phrase or source-authored origin claim is determined.'}
            elif glyph=='Γ':action={'book_ii_role':op['book_ii_role'],'contextual_application':'Address the frame around the accumulated path at this occurrence.','actual_relationship_recorded':{'frame_cell':list(xy),'all_neighbor_connections':node['neighbors'],'degree':node['degree'],'retained_prior_frames':incoming['frame_occurrences']},'semantic_resolution':'Measured frame membership/adjacency retained; delimiter significance remains open.'}
            elif glyph=='Λ':action={'book_ii_role':op['book_ii_role'],'contextual_application':'Address the path relation on reaching this lattice occurrence.','actual_relationship_recorded':{'core_reentry':xy in core and previous is not None and tuple(previous) not in core,'retained_neighbors':node['neighbors'],'incoming_path':incoming['visited_containers']},'semantic_resolution':'Actual re-entry or departure connections retained; onward paths remain available.'}
            elif glyph=='Ε':action={'book_ii_role':op['book_ii_role'],'contextual_application':'Address the scope threshold reached with the current incoming route.','actual_relationship_recorded':{'coordinate':list(xy),'core_member':xy in core,'incoming_from_core':None if previous is None else tuple(previous) in core,'next_in_core':None if nextcell is None else tuple(nextcell) in core,'perimeter_refs':[b['id'] for b in boundary if b['from']==list(xy)]},'semantic_resolution':'Scope crossing and retained perimeter are recorded; no terminal closure is inserted.'}
            elif glyph=='Δ':action={'book_ii_role':op['book_ii_role'],'contextual_application':'Address change relative to the prior occurrence and arrival context.','actual_relationship_recorded':{'prior_occurrence':incoming['current_occurrence'],'current_occurrence':ref,'previous_source_value':None if previous is None else nodes[tuple(previous)]['value'],'current_source_value':node['value'],'same_container_as_previous_glyph':incoming['current_occurrence'] is not None and incoming['current_occurrence']['coordinate']==list(xy)},'semantic_resolution':'Occurrence/context differences recorded; their source-authored meaning remains open.'}
            else:action={'book_ii_role':op['book_ii_role'],'contextual_application':'Address the stated BookII role in this exact incoming path context.','actual_relationship_recorded':{'previous_same_role_occurrences':incoming[bucket],'current_role_occurrence':ref,'source_cell_and_container_unchanged':True,'all_alternatives_retained':alternatives},'semantic_resolution':'Measured source/container/path relationships are retained; no unique additional semantic result is stipulated.'}
            entries.append({'route':t['route'],'exit':t['exit'],'direction':t['orientation'],'occurrence':op['occurrence'],'input_relation':incoming,'source':observed,'glyph':glyph,'action':action,'output_relation':json.loads(json.dumps(state)),'retained_remainder':{'all_source_neighbors':node['neighbors'],'boundary_refs':[b['id'] for b in boundary if b['from']==list(xy)],'source_container_identity':list(xy),'route_endpoint_is_not_message_EOF':True,'unresolved':'Source semantics and a unique decoded message remain unassigned by this trace record.'},'native_action_separate':{'register_order':REGS,'before':op['native_before'],'after':op['native_after'],'changed_registers':op['native_changed_registers']}})
